class CannotStartPrisma(Exception):
    def __init__(self, node_name):
        """
        Can not start prisma

        :param node_name:
        """
        self.node_name = node_name


class CannotStartLSU(CannotStartPrisma):
    def __str__(self):
        return "Can not start LSU for node:{}".format(self.node_name)


class CannotStartTSTM(CannotStartPrisma):
    def __str__(self):
        return "Can not start TSTM for node:{}".format(self.node_name)


class CannotStartEPC(CannotStartPrisma):
    def __str__(self):
        return "Can not start EPC for node:{}".format(self.node_name)


class CannotStartS1(CannotStartPrisma):
    def __str__(self):
        return "Can not start S1 link on EPC for node:{}".format(self.node_name)


class CannotInitEPC(CannotStartPrisma):
    def __str__(self):
        return "Can not init epc for node:{}".format(self.node_name)


class CannotAttach(CannotStartPrisma):
    def __str__(self):
        return "Failed to attach for node:{}".format(self.node_name)


class CannotDetach(Exception):
    def __init__(self, node_name):
        """

        :param node_name:
        """
        self.node_name = node_name

    def __str__(self):
        return "Failed to detach for node:{}".format(self.node_name)


class ScenarioMessageCannotMatch(Exception):
    def __init__(self, expected_msg, last_msg, timeout):
        self.timeout = timeout
        self.expected_msg = expected_msg
        self.last_msg = last_msg

    def __str__(self):
        pattern = "timeout {}s, expected message is {}, last message is {}"
        return pattern.format(self.timeout, self.expected_msg, self.last_msg)


class CannotStartTraffic(ScenarioMessageCannotMatch):
    def __init__(self, e):
        super(CannotStartTraffic, self).__init__(e.expected_msg, e.last_msg, e.timeout)

    def __str__(self):
        upper_level_str = super(CannotStartTraffic).__str__()
        return "Failed to start traffic cause: /n" + upper_level_str


def scenario_message_exception(user_exception):
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except ScenarioMessageCannotMatch as e:
                raise user_exception(e)
        return wrapper

    return decorator
